execute-script.function:
{
    catalog = if($container.instanceOf(`ehome.catalog:Catalog`),
        $container,
        $container.referers(`ehome.catalog:Catalog#variants`).firstElement());
    product = if($container.instanceOf(`ehome.catalog:Variant`),
        $container.get(`ehome.catalog:Variant#product`),
        {
            manufacturer = recursion($catalog, x -> $x.container())
                .filter(x -> $x.instanceOf(`ehome.catalog:Manufacturer`))
                .firstElement();
            created = new(`ehome.catalog:Product`);
            $created.set(`ehome.catalog:Product#name`, $variant.get(`ehome.catalog:Variant#name`).localize());
            $manufacturer.add(`ehome.catalog:Manufacturer#products`, $created);
            $created
        });
    $product.add(`ehome.catalog:Product#variants`, $variant);
    $catalog.add(`ehome.catalog:Catalog#variants`, $variant);
    $variant
}
